#!/usr/bin/env bash
# Compile a list of variants with the NPUC oracle (npuc-local.sh), up to 6 at once, for the CMDQ stream mapping
# (docs/format/cmdq.md). Each spec line: "<name> [quant=1|3] [none] <npuc-variant.py args after the out path>";
# '#' starts a comment. A variant dir that already has net.ncp is skipped unless FORCE=1.
#   ncpgen/stream_sweep.sh <specfile> [<outroot>]        (default outroot: $NCPGEN_WORK/sweep/stream)
# Prints one line per variant: "ok <name>" or "FAIL <name> <reason>". The compiled NCPs and logs stay in outroot
# (git-ignored): vendor-generated bytes, never committed.
set -uo pipefail
HERE=$(cd "$(dirname "$0")" && pwd)
. "$HERE/../oracle/env.sh"
SPEC=${1:?specfile}
ROOT=${2:-$NCPGEN_WORK/sweep/stream}
mkdir -p "$ROOT/v"
one() {
  local line=$1 name q=1 none= args=()
  read -r -a f <<<"$line"
  name=${f[0]}
  for x in "${f[@]:1}"; do
    case "$x" in
      quant=*) q=${x#quant=} ;;
      none) none=--allow-none ;;
      *) args+=("$x") ;;
    esac
  done
  local d=$ROOT/$name
  if [ -s "$d/net.ncp" ] && [ "${FORCE:-0}" != 1 ]; then echo "ok $name (cached)"; return; fi
  python3 -I "$ORACLE/npuc-variant.py" "$ROOT/v/$name.json" "${args[@]}" >/dev/null 2>"$ROOT/v/$name.err" \
    || { echo "FAIL $name variant: $(tail -n1 "$ROOT/v/$name.err")"; return; }
  local out
  out=$(bash "$ORACLE/npuc-local.sh" "$ROOT/v/$name.json" "$d" --quant "$q" $none 2>&1)
  if [ -s "$d/net.ncp" ] && printf '%s' "$out" | grep -q 'npuc-local: PASS'; then echo "ok $name"
  else echo "FAIL $name $(printf '%s' "$out" | tail -n 1)"; fi
}
export -f one
export ROOT P
grep -v '^\s*#' "$SPEC" | grep -v '^\s*$' | tr '\n' '\0' | xargs -0 -P 6 -I{} bash -c 'one "$1"' _ {}
